import flax.linen as nn
import jax.numpy as jnp
from typing import Any, Dict

def _define_hyperparameters():
    """Define hyperparameter values for the model."""
    return {
        'learning_rate': 0.001,
        'num_filters': 128,
        'dropout_rate': 0.2,
        'kernel_size': 7
    }

class ConvBlock(nn.Module):
    """A single convolutional block."""
    num_filters: int
    kernel_size: int

    @nn.compact
    def __call__(self, x):
        x = nn.Conv(features=self.num_filters, kernel_size=(self.kernel_size,), padding='SAME')(x)
        x = nn.relu(x)
        return x

class DeeperCNN(nn.Module):
    """A deeper 1D CNN with a residual connection."""
    d_output: int
    task_type: str
    num_filters: int
    dropout_rate: float
    kernel_size: int

    @nn.compact
    def __call__(self, x, deterministic=True):
        # Input shape: (batch_size, seq_len, 4)

        # First convolutional block
        x = ConvBlock(num_filters=self.num_filters, kernel_size=self.kernel_size)(x)

        # Second convolutional block with a residual connection
        x_res = x
        x = ConvBlock(num_filters=self.num_filters, kernel_size=self.kernel_size)(x)
        x = x + x_res # Add residual

        # Global average pooling over the sequence length
        x = jnp.mean(x, axis=1) # Shape: (batch_size, num_filters)

        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)

        # Final dense layer for prediction
        x = nn.Dense(features=self.d_output)(x)

        if self.task_type == "regression":
            return x.squeeze(-1)  # Shape: (batch_size,)
        else:
            return x  # Shape: (batch_size, d_output)

class CNNNetwork:
    """Wrapper for the CNN model to match the required interface."""
    def __init__(self, **kwargs):
        self.network = DeeperCNN(**kwargs)

    def init(self, rng_key, dummy_input):
        return self.network.init(rng_key, dummy_input, deterministic=True)['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        return self.network.apply({'params': params}, x, deterministic=deterministic, rngs={'dropout': rng_key} if not deterministic else None)

def create_network(hparams: Dict[str, Any]):
    """Create and return the CNN network."""
    return CNNNetwork(
        d_output=hparams.get("d_output"),
        task_type=hparams.get("task_type"),
        num_filters=hparams.get("num_filters"),
        dropout_rate=hparams.get("dropout_rate"),
        kernel_size=hparams.get("kernel_size")
    )
